<script setup lang="ts">import { onMounted, ref } from 'vue'; import { getSales } from '../api'; import type { SaleSummary } from '../types'; import { errorMessage } from '../../catalog/api'
const items=ref<SaleSummary[]>([]), total=ref(0), orderNo=ref(''), fromDate=ref(''), toDate=ref(''), alert=ref('')
async function load(){try{const page=await getSales({...(orderNo.value?{orderNo:orderNo.value}:{}),...(fromDate.value?{fromDate:fromDate.value}:{}),...(toDate.value?{toDate:toDate.value}:{}),page:0,size:50});items.value=page.items;total.value=page.total}catch(cause){alert.value=errorMessage(cause)}}onMounted(load)
</script>
<template><main class="page"><header><div><p>出货管理</p><h1>销售记录</h1></div><RouterLink to="/sales">返回收银台</RouterLink></header><section class="card filters"><label>开始日期<input v-model="fromDate" type="date"></label><label>结束日期<input v-model="toDate" type="date"></label><label>销售单号<input v-model="orderNo"></label><button type="button" @click="load">查询</button></section><p v-if="alert" role="alert">{{alert}}</p><section class="card"><p>共 {{total}} 笔</p><table><thead><tr><th>销售单号</th><th>时间</th><th>实收</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td>{{item.orderNo}}</td><td>{{item.occurredAt}}</td><td>¥{{item.actualAmount.toFixed(2)}}</td><td>{{item.status}}</td><td><RouterLink :to="`/sales/${item.id}`">查看详情</RouterLink></td></tr></tbody></table></section></main></template>
<style scoped>.page{display:grid;gap:1rem;max-width:78rem;margin:auto}header,.filters{display:flex;justify-content:space-between;align-items:end;gap:1rem}.card{background:#fff;border:1px solid #e2e8f0;border-radius:.8rem;padding:1rem}.filters label{display:grid;gap:.3rem}input,button{padding:.6rem}table{width:100%;border-collapse:collapse}th,td{padding:.7rem;border-bottom:1px solid #e2e8f0;text-align:left}</style>
